mapper.insert:
INSERT INTO notifications (member_id, notification_type, title, message, related_id, event_date, is_read)
SELECT member_id, #{type}, #{title}, #{content}, #{relatedId}, #{eventDate}, false
FROM member WHERE email = #{userId}

mapper.update:
UPDATE notifications
SET is_read = true, read_at = NOW()
WHERE notification_id = #{notificationId}

mapper.select:
SELECT COUNT(*) > 0
FROM notifications n
JOIN member m ON n.member_id = m.member_id
WHERE m.email = #{userId}
  AND n.notification_type = #{type}
  AND n.event_date = #{eventDate}
  AND n.title = #{title}
  AND n.deleted_at IS NULL

mapper.update:
